#include <utility>   // for std::pair

// Returns the minimum and maximum number of active groups
// according to the scheduling rules described in the task.
std::pair<int, int> groupStats(int n, int k) {
    // Minimum: 0 exactly when k is 0 or k equals n; otherwise 1.
    int minVal = (k == 0 || k == n) ? 0 : 1;

    // Maximum: depends on whether k is at most floor(n/3).
    int maxVal = (k <= n / 3) ? 2 * k : n - k;

    return {minVal, maxVal};
}
